224:     private static byte[] HashPayload(NormalizedStudent student) => SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(Columns.Keys.Where(key=>key is not ("name_key" or "kana_key" or "relationship_category")).Select(key=>new KeyValuePair<string,object?>(key,student.Values[key])))));
