226:     private static SaveResult Result(Outcome outcome,string code,string message,string requestId) => new(outcome,null,null,[new("",code,message)],RequestId:requestId);
227:     public async Task<SaveResult> SaveAsync(SaveRequest request,CancellationToken ct = default)
228:     {
